CREATE TABLE IF NOT EXISTS juntas (id TEXT PRIMARY KEY, nombre TEXT NOT NULL, activa INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS presidentes (id TEXT PRIMARY KEY, junta_id TEXT NOT NULL REFERENCES juntas(id), usuario TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, hash TEXT NOT NULL, activo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS solicitudes (codigo TEXT PRIMARY KEY, junta_id TEXT NOT NULL REFERENCES juntas(id), nombre TEXT NOT NULL, direccion TEXT NOT NULL, contacto TEXT NOT NULL, requerimiento TEXT NOT NULL, estado TEXT NOT NULL DEFAULT 'pendiente_presidente', creada TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, actualizada TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, revision_municipal TEXT, folio_sgt TEXT);
CREATE TABLE IF NOT EXISTS eventos (id INTEGER PRIMARY KEY AUTOINCREMENT, codigo TEXT NOT NULL REFERENCES solicitudes(codigo), estado TEXT NOT NULL, actor TEXT NOT NULL, detalle TEXT NOT NULL DEFAULT '', fecha TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_solicitudes_junta_estado ON solicitudes(junta_id,estado);
CREATE INDEX IF NOT EXISTS idx_eventos_codigo ON eventos(codigo);
CREATE TABLE IF NOT EXISTS sesiones (token_hash TEXT PRIMARY KEY, presidente_id TEXT NOT NULL, expira TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sincronizaciones (codigo TEXT PRIMARY KEY, folio_sgt TEXT NOT NULL, fecha TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
